<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {usePhasePage} from '../phasePage'
import {useDocumentExpiryText} from '../documentExpiry'
import {useDocumentText} from '../documentText'
import {prepareDocumentFile} from '../documentImages'
import {WorkforceApiError} from '../api'
import type {DocumentPage,EmployeeDocument,DocumentRecognition,DocumentAttachment,DocumentPreviewSource} from '../documentTypes'
import PhaseStatus from './PhaseStatus.vue'
import DocumentRecognitionReview from './DocumentRecognitionReview.vue'
import DocumentAttachmentPreview from './DocumentAttachmentPreview.vue'
import DocumentEditorDialog from './DocumentEditorDialog.vue'
const props=defineProps<{employeeId:string;documentId?:string;editorOnly?:boolean;dialogTitle?:string;embedded?:boolean}>(),{api,current,store,t,p,load,loading,failure,notice}=usePhasePage(),{d}=useDocumentText()
const emit=defineEmits<{changed:[];close:[];blocked:[value:boolean]}>(),{x}=useDocumentExpiryText();let opened=false,epoch=0
const emptyForm=()=>({id:'',expectedVersion:0,typeId:'',holderName:'',number:'',approvedOn:'',prEffectiveOn:'',expiresOn:'',notes:''})
const data=ref<DocumentPage>({types:[],items:[]}),editing=ref(false),busy=ref(false),recognizing=ref(false),form=ref(emptyForm()),pending=ref<{doc:string;id:string;version:number;file:File}|null>(null),lastSize=ref(0),suggestion=ref<DocumentRecognition|null>(null),ocrFailure=ref('')
const dialogOpen=ref(!!props.documentId)
const preview=ref<{documentId:string;source:DocumentPreviewSource}|null>(null)
const base=computed(()=>`/employees/${encodeURIComponent(props.employeeId)}/documents`),blocked=computed(()=>busy.value||recognizing.value||!!pending.value)
watch(blocked,value=>emit('blocked',value),{immediate:true})
function scope(){const revision=epoch,owner=store.value,employee=props.employeeId;return ()=>current()&&revision===epoch&&owner===store.value&&employee===props.employeeId}
function report(e:unknown){if(e instanceof WorkforceApiError){failure.value=e.status===409?d('stale'):e.status===403?p('noAccess'):e.code==='WORKFORCE_DOCUMENT_FILE_TOO_LARGE'?d('largeFile'):e.code==='WORKFORCE_DOCUMENT_ATTACHMENT_LIMIT'?d('attachmentLimit'):e.code==='WORKFORCE_DOCUMENT_FILE_INVALID'?d('invalidFile'):p('invalid')}else failure.value=e instanceof Error&&e.message==='largeFile'?d('largeFile'):d('invalidFile')}
function resetEditor(){dialogOpen.value=false;editing.value=false;preview.value=null;suggestion.value=null;ocrFailure.value=''}
function closeEditor(){if(blocked.value||loading.value)return;resetEditor();failure.value='';if(!props.editorOnly)reload();emit('close')}
function reload(keepEditor=false){const active=scope();if(!keepEditor&&!props.editorOnly)resetEditor();preview.value=null;editing.value=false;suggestion.value=null;ocrFailure.value='';void load(()=>api().get<DocumentPage>(base.value),result=>{if(!active())return;data.value={...result,items:props.documentId?result.items.filter(row=>row.id===props.documentId):result.items};if(props.documentId&&(!opened||keepEditor)){opened=true;const row=data.value.items[0];if(row)edit(row);else failure.value=x('missing')}})}
function edit(row?:EmployeeDocument){if(blocked.value)return;if(suggestion.value?.documentId!==row?.id)suggestion.value=null;form.value=row?{id:row.id,expectedVersion:row.version,typeId:row.typeId,holderName:row.holderName||'',number:row.number,approvedOn:row.approvedOn||'',prEffectiveOn:row.prEffectiveOn||'',expiresOn:row.expiresOn||'',notes:row.notes}:{...emptyForm(),id:crypto.randomUUID()};editing.value=true;dialogOpen.value=true;failure.value='';notice.value='';preview.value=null;if(row?.attachments[0])setPreview(row,row.attachments[0])}
function datesValid(){return !form.value.expiresOn||![form.value.approvedOn,form.value.prEffectiveOn].some(date=>date&&date>form.value.expiresOn)}
async function save(){if(blocked.value)return;if(!datesValid()){failure.value=d('dateOrder');return}busy.value=true;failure.value='';const active=scope();try{await api().put(base.value+'/'+form.value.id,{...form.value,approvedOn:form.value.approvedOn||null,prEffectiveOn:form.value.prEffectiveOn||null,expiresOn:form.value.expiresOn||null});if(active()){notice.value=d('saved');reload(!!props.editorOnly);emit('changed')}}catch(e){if(active())report(e)}finally{if(active())busy.value=false}}
async function remove(row:EmployeeDocument){if(blocked.value||!window.confirm(d('confirmDelete')))return;busy.value=true;failure.value='';const active=scope();try{await api().put(base.value+'/'+row.id,{expectedVersion:row.version,typeId:row.typeId,holderName:row.holderName||'',number:row.number,approvedOn:row.approvedOn||null,prEffectiveOn:row.prEffectiveOn||null,expiresOn:row.expiresOn,notes:row.notes,deleted:true});if(active()){resetEditor();if(props.editorOnly)emit('close');else reload();emit('changed')}}catch(e){if(active())report(e)}finally{if(active())busy.value=false}}
function setPreview(row:EmployeeDocument,file:DocumentAttachment,local?:File){if(suggestion.value&&(suggestion.value.documentId!==row.id||suggestion.value.attachmentId!==file.id))suggestion.value=null;preview.value={documentId:row.id,source:{path:base.value+'/'+row.id+'/attachments/'+file.id,file:local,filename:file.filename,contentType:file.contentType}}}
function openPreview(row:EmployeeDocument,file:DocumentAttachment){if(blocked.value)return;if(!editing.value||form.value.id!==row.id)edit(row);setPreview(row,file)}
async function choose(row:EmployeeDocument|undefined,event:Event){
 const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||blocked.value)return
 if(!row&&(!form.value.typeId||form.value.expectedVersion)){failure.value=form.value.expectedVersion?d('stale'):d('chooseTypeFirst');return}
 if(row&&(!editing.value||form.value.id!==row.id))edit(row)
 busy.value=true;failure.value='';const active=scope()
 try{
  const ready=await prepareDocumentFile(file);if(!active())return
  if(!row){const created=await api().put<EmployeeDocument>(base.value+'/'+form.value.id,{expectedVersion:0,typeId:form.value.typeId,number:'',holderName:'',approvedOn:null,prEffectiveOn:null,expiresOn:null,notes:'',deleted:false});if(!active())return;row=created;form.value.expectedVersion=created.version;if(!data.value.items.some(item=>item.id===created.id))data.value.items.push(created);emit('changed')}
  lastSize.value=ready.type.startsWith('image/')?ready.size:0
  pending.value={doc:row.id,id:crypto.randomUUID(),version:row.version,file:ready}
  setPreview(row,{id:pending.value.id,filename:ready.name,contentType:ready.type,size:ready.size},ready)
 }catch(e){if(active())report(e)}finally{if(active())busy.value=false}
 if(active()&&pending.value)await upload()
}
async function upload(){if(busy.value||!pending.value)return;const request=pending.value,active=scope(),client=api(),path=base.value;busy.value=true;failure.value='';try{const updated=await client.upload<EmployeeDocument>(path+'/'+request.doc+'/attachments/'+request.id,request.file,request.version);if(active()){pending.value=null;data.value.items=data.value.items.map(row=>row.id===updated.id?updated:row);if(editing.value&&form.value.id===updated.id)form.value.expectedVersion=updated.version;emit('changed');busy.value=false;await recognize(updated,request.id)}}catch(e){if(active()){if(e instanceof WorkforceApiError&&e.status>=400&&e.status<500){pending.value=null;report(e)}else failure.value=d('retry')}}finally{if(active())busy.value=false}}
async function recognize(row:EmployeeDocument,id:string){if(blocked.value)return;if(!editing.value||form.value.id!==row.id)edit(row);const source=row.attachments.find(file=>file.id===id);if(source&&(!preview.value||preview.value.documentId!==row.id||!preview.value.source.path?.endsWith('/'+id)))setPreview(row,source);const active=scope(),version=row.version;recognizing.value=true;suggestion.value=null;ocrFailure.value='';try{const result=await api().put<DocumentRecognition>(base.value+'/'+row.id+'/attachments/'+id+'/recognition',{expectedVersion:version});if(active()){const latest=data.value.items.find(item=>item.id===row.id);if(result.documentId!==row.id||result.attachmentId!==id||result.documentVersion!==version||latest?.version!==version){ocrFailure.value=d('recognitionStale');return}suggestion.value=result}}catch(e){if(active())ocrFailure.value=e instanceof WorkforceApiError&&e.status===409?d('recognitionStale'):d('recognitionFailure')}finally{if(active())recognizing.value=false}}
function applyRecognition(values:Partial<Record<'holderName'|'number'|'approvedOn'|'expiresOn'|'prEffectiveOn',string>>){const result=suggestion.value,row=data.value.items.find(item=>item.id===result?.documentId);if(blocked.value||!result)return;if(!row||row.version!==result.documentVersion){suggestion.value=null;ocrFailure.value=d('recognitionStale');return}if(!editing.value||form.value.id!==row.id)edit(row);Object.assign(form.value,values);suggestion.value=null}
async function removeFile(row:EmployeeDocument,id:string){if(blocked.value||!window.confirm(d('confirmFile')))return;busy.value=true;failure.value='';const active=scope();try{const updated=await api().put<EmployeeDocument>(base.value+'/'+row.id+'/attachments/'+id+'/deletion',{expectedVersion:row.version});if(active()){data.value.items=data.value.items.map(item=>item.id===updated.id?updated:item);if(form.value.id===updated.id)form.value.expectedVersion=updated.version;if(preview.value?.source.path?.endsWith('/'+id))preview.value=null;suggestion.value=null;emit('changed')}}catch(e){if(active())report(e)}finally{if(active())busy.value=false}}
watch(()=>[store.value,props.employeeId,props.documentId],()=>{epoch++;opened=false;busy.value=false;recognizing.value=false;pending.value=null;resetEditor();dialogOpen.value=!!props.documentId;data.value={types:[],items:[]};reload()},{flush:'sync'})
onMounted(reload)
</script>
<template><section :class="{'wf-panel':!editorOnly&&!embedded}"><template v-if="!editorOnly"><header class="wf-toolbar"><h2 v-if="!embedded">{{d('title')}}</h2><div class="wf-inline"><button type="button" :disabled="blocked||loading" @click="reload()">{{p('reload')}}</button><button v-if="!documentId" type="button" class="primary" :disabled="blocked||loading||!!failure" @click="edit()">{{d('add')}}</button></div></header><p class="wf-hint">{{d('fileHint')}}</p><PhaseStatus :loading="loading" :failure="failure" :notice="notice"/><p v-if="busy" role="status">{{d('processing')}}</p><p v-if="lastSize" class="wf-hint">{{d('compressed')}} {{Math.ceil(lastSize/1024)}}KB / 1024KB</p><button v-if="pending" type="button" :disabled="busy" @click="upload">{{d('retryAction')}}</button>
 <div v-if="!failure&&(!loading||data.items.length)" class="wf-table-wrap"><table><thead><tr><th>{{d('type')}}</th><th>{{d('holderName')}}</th><th>{{d('number')}}</th><th>{{d('approvedOn')}}</th><th>{{d('prEffectiveOn')}}</th><th>{{d('expiry')}}</th><th>{{d('notes')}}</th><th>{{d('attachments')}}</th><th>{{t('manage')}}</th></tr></thead><tbody><tr v-for="row in data.items" :key="row.id"><td>{{row.typeName}}</td><td>{{row.holderName||'—'}}</td><td>{{row.number||'—'}}</td><td>{{row.approvedOn||'—'}}</td><td>{{row.prEffectiveOn||'—'}}</td><td>{{row.expiresOn||'—'}}</td><td class="wf-wrap-text">{{row.notes||'—'}}</td><td><div v-for="file in row.attachments" :key="file.id" class="wf-inline"><button type="button" :disabled="blocked" @click="openPreview(row,file)">{{d('preview')}} · {{file.filename}} · {{Math.ceil(file.size/1024)}}KB</button><a :href="api().url(base+'/'+row.id+'/attachments/'+file.id)" target="_blank" rel="noopener">{{d('download')}}</a><button v-if="file.contentType.startsWith('image/')||file.contentType==='application/pdf'" type="button" :disabled="blocked" @click="recognize(row,file.id)">{{d('recognize')}}</button><button type="button" :disabled="blocked" @click="removeFile(row,file.id)">{{d('remove')}}</button></div><button v-if="row.attachments.length<5" type="button" :disabled="blocked" @click="edit(row)">{{d('upload')}}</button></td><td><div class="wf-inline"><button type="button" :disabled="blocked" @click="edit(row)">{{d('edit')}}</button><button type="button" :disabled="blocked" @click="remove(row)">{{d('delete')}}</button></div></td></tr><tr v-if="!data.items.length"><td colspan="9" class="wf-empty">{{d('empty')}}</td></tr></tbody></table></div>
</template> <DocumentEditorDialog v-if="dialogOpen" :title="dialogTitle||d('dialogTitle')" :disabled="blocked||loading" @close="closeEditor"><PhaseStatus :loading="loading" :failure="failure" :notice="notice"/><p v-if="busy" role="status">{{d('processing')}}</p><p v-if="lastSize" class="wf-hint">{{d('compressed')}} {{Math.ceil(lastSize/1024)}}KB / 1024KB</p><button v-if="pending" type="button" :disabled="busy" @click="upload">{{d('retryAction')}}</button><div class="wf-document-review has-preview"><DocumentAttachmentPreview v-if="preview" :source="preview.source" @close="preview=null"/><aside v-else class="wf-preview-placeholder"><h3>{{d('previewTitle')}}</h3><p class="wf-hint">{{d('previewAfterUpload')}}</p></aside><div class="wf-document-editor"><div v-if="editing" class="wf-inline"><template v-for="file in data.items.find(row=>row.id===form.id)?.attachments||[]" :key="file.id"><button type="button" :disabled="blocked" @click="openPreview(data.items.find(row=>row.id===form.id)!,file)">{{d('preview')}} · {{file.filename}}</button><button type="button" :disabled="blocked" @click="recognize(data.items.find(row=>row.id===form.id)!,file.id)">{{d('recognize')}}</button><button type="button" :disabled="blocked" @click="removeFile(data.items.find(row=>row.id===form.id)!,file.id)">{{d('remove')}}</button></template></div><p v-if="recognizing" role="status">{{d('recognitionBusy')}}</p><p v-if="ocrFailure" role="alert">{{ocrFailure}}</p><DocumentRecognitionReview v-if="suggestion" :key="suggestion.documentId+':'+suggestion.attachmentId+':'+suggestion.documentVersion" :suggestion="suggestion" :disabled="blocked" @apply="applyRecognition" @dismiss="suggestion=null"/>
 <form v-if="editing" @submit.prevent="save"><fieldset :disabled="blocked"><div class="wf-grid"><label>{{d('type')}}<select v-model="form.typeId" required><option value="" disabled>{{t('select')}}</option><option v-for="type in data.types.filter(type=>type.enabled||type.id===form.typeId)" :key="type.id" :value="type.id">{{type.name}}{{type.enabled?'':' · '+d('disabled')}}</option></select></label><div class="wf-editor-upload"><label>{{d('uploadEditor')}}<input type="file" accept="image/jpeg,image/png,image/webp,application/pdf" :aria-label="d('uploadEditor')" :disabled="blocked||!form.typeId||(data.items.find(row=>row.id===form.id)?.attachments.length||0)>=5" @change="choose(data.items.find(row=>row.id===form.id),$event)"></label><p class="wf-hint">{{d('uploadEditorHint')}}</p></div><label>{{d('holderName')}}<input v-model="form.holderName" :aria-label="d('holderName')" maxlength="100"><small>{{d('holderHint')}}</small></label><label>{{d('number')}}<input v-model="form.number" :aria-label="d('number')" maxlength="100"></label><label>{{d('expiry')}}<input v-model="form.expiresOn" :aria-label="d('expiry')" type="date"></label><label>{{d('approvedOn')}}<input v-model="form.approvedOn" :aria-label="d('approvedOn')" type="date" :max="form.expiresOn||undefined"></label><label>{{d('prEffectiveOn')}}<input v-model="form.prEffectiveOn" :aria-label="d('prEffectiveOn')" type="date" :max="form.expiresOn||undefined"><small>{{d('prHint')}}</small></label><label>{{d('notes')}}<textarea v-model="form.notes" maxlength="2000" rows="2"/></label></div></fieldset><footer class="wf-form-actions"><button v-if="form.expectedVersion&&data.items.find(row=>row.id===form.id)" type="button" :disabled="blocked" @click="remove(data.items.find(row=>row.id===form.id)!)">{{d('delete')}}</button><button type="button" :disabled="blocked" @click="closeEditor">{{t('cancel')}}</button><button type="submit" class="primary" :disabled="blocked">{{t('save')}}</button></footer></form>
 </div></div></DocumentEditorDialog>

</section></template>

<style scoped>.wf-document-review{display:grid;grid-template-columns:minmax(0,1fr);gap:16px;margin:14px 0}.wf-document-review.has-preview{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.wf-document-editor{min-width:0}.has-preview .wf-grid{grid-template-columns:minmax(0,1fr)}.wf-preview-placeholder{padding:16px;border:1px dashed #ccd9e5;border-radius:8px;min-height:220px}.wf-editor-upload{grid-column:1/-1;padding:12px;background:#f4f7fa;border:1px solid #dce5ed;border-radius:6px}.wf-editor-upload input{display:block;margin-top:8px;max-width:100%}@media(max-width:800px){.wf-document-review.has-preview{grid-template-columns:minmax(0,1fr)}}</style>
